38	    private static final class DisjointSet {
39	        private final int[] parent;
40	        private final int[] rank;
41	
42	        private DisjointSet(int size) {
43	            if (size < 0) {
44	                throw new IllegalArgumentException("Disjoint set size must be non-negative.");
45	            }
46	
47	            this.parent = new int[size];
48	            this.rank = new int[size];
49	            for (int i = 0; i < size; i++) {
50	                parent[i] = i;
51	                rank[i] = 0;
52	            }
53	        }
54	
55	        private int find(int node) {
56	            validateNode(node);
57	            if (parent[node] != node) {
58	                parent[node] = find(parent[node]);
59	            }
60	            return parent[node];
61	        }
