63	        private boolean union(int first, int second) {
64	            validateNode(first);
65	            validateNode(second);
66	
67	            int rootFirst = find(first);
68	            int rootSecond = find(second);
69	            if (rootFirst == rootSecond) {
70	                return false;
71	            }
72	
73	            if (rank[rootFirst] < rank[rootSecond]) {
74	                parent[rootFirst] = rootSecond;
75	            } else if (rank[rootFirst] > rank[rootSecond]) {
76	                parent[rootSecond] = rootFirst;
77	            } else {
78	                parent[rootSecond] = rootFirst;
79	                rank[rootFirst]++;
